def lines_for_old_invoices(apps, schema_editor):
    """Every invoice already made for a Sales person's deal gets its line: the whole of it theirs, pending, at whatever
    rate the owner sets. A cancelled invoice gets none."""
    Invoice = apps.get_model("dashboard", "Invoice")
    Commission = apps.get_model("dashboard", "Commission")
    number = 0
    for invoice in Invoice.objects.filter(owner__isnull=False).exclude(status="cancelled").order_by("id"):
        number += 1
        Commission.objects.create(code=f"COM-{number:04d}", invoice=invoice, person_id=invoice.owner_id)


